import numpy as np
import pandas as pd

BARS5 = [f"{h:02d}:{mm:02d}" for h in range(9, 16) for mm in range(0, 60, 5) if (9, 15) <= (h, mm) <= (15, 25)]
NB5 = len(BARS5)
TOPN = 200
MINW, MAXW, RVOL_MIN, TRAIL_K, WARMUP = 0.004, 0.015, 2.0, 0.25, 5



class P:  # parameters from SPEC.md (5-minute version)
    def __init__(self, **kw):
        self.nb = NB5; self.win_lo = BARS5.index("09:40"); self.win_hi = BARS5.index("14:25"); self.exit_idx = BARS5.index("15:10")
        self.watch = 12; self.ext = 0.5; self.touch = 0.2; self.buf = 0.1; self.rmin = 0.002; self.rmax = 0.01
        self.piv = 2; self.spacing = 3; self.tol = 0.25; self.sweep = 0.05; self.far = 1.0; self.rr = 2.0
        self.be = True; self.atr_n = 14; self.drop_first_vol = False; self.tf = 5
        self.__dict__.update(kw)


def indicators(arr, good, p):
    """VWAP per day and ATR over the stock's continuous series of valid bars (first bar of a day uses high-low)."""
    o, h, l, c, v = (arr[f] for f in ("o", "h", "l", "c", "v"))
    nd, nb = c.shape
    vol = np.nan_to_num(v.copy(), nan=0.0)
    if p.tf == 5:
        if p.drop_first_vol:
            vol[:, 0] = 0.0
        else:
            fix = (vol[:, 0] <= 0) & ~np.isnan(c[:, 0])
            vol[fix, 0] = np.nan_to_num(v[fix, 1], nan=0.0)
    tp = np.nan_to_num((h + l + c) / 3.0, nan=0.0)
    vol = np.where(np.isnan(c), 0.0, vol)
    cv = np.cumsum(tp * vol, 1); cvol = np.cumsum(vol, 1)
    with np.errstate(all="ignore"):
        vw = np.where(cvol > 0, cv / cvol, np.nan)
    # ATR
    flat = pd.DataFrame({"h": h.ravel(), "l": l.ravel(), "c": c.ravel(), "day": np.repeat(np.arange(nd), nb)})
    val = flat.dropna(subset=["h", "l", "c"])
    pc = val.c.shift(1).where(val.day.shift(1) == val.day)
    tr = np.maximum(val.h - val.l, np.maximum((val.h - pc).abs(), (val.l - pc).abs()).fillna(0))
    atr = tr.rolling(p.atr_n, min_periods=p.atr_n).mean()
    A = np.full(nd * nb, np.nan); A[val.index.values] = atr.values
    return vw, A.reshape(nd, nb)


def ok(x):
    return x == x


def find_a(o, h, l, c, v, vw, at, p):
    """First Setup-A signal of the day (either side). Returns (side, i, stop) or None."""
    ws = {1: None, -1: None}; ext = {1: -np.inf, -1: np.inf}; prev = None
    for i in range(p.nb):
        if not (ok(c[i]) and ok(vw[i])):
            continue
        for s in (1, -1):
            if ws[s] is None:
                continue
            if s * (c[i] - vw[i]) < 0 or i - ws[s] > p.watch:
                ws[s] = None; continue
            a = at[i]
            if ok(a) and a > 0 and p.win_lo <= i <= p.win_hi:
                if s > 0:
                    sig = (ext[s] - vw[i] >= p.ext * a) and (l[i] <= vw[i] + p.touch * a) and c[i] > vw[i] and c[i] > o[i]
                    stop = min(l[i], vw[i]) - p.buf * a
                else:
                    sig = (vw[i] - ext[s] >= p.ext * a) and (h[i] >= vw[i] - p.touch * a) and c[i] < vw[i] and c[i] < o[i]
                    stop = max(h[i], vw[i]) + p.buf * a
                if sig:
                    risk = s * (c[i] - stop)
                    if p.rmin <= risk / c[i] <= p.rmax and ok(o[i + 1]) and v[i] > 0:
                        return s, i, stop
            ext[s] = max(ext[s], h[i]) if s > 0 else min(ext[s], l[i])
        if prev is not None:
            if c[i] > vw[i] and c[prev] <= vw[prev]:
                ws[1] = i; ext[1] = h[i]
            if c[i] < vw[i] and c[prev] >= vw[prev]:
                ws[-1] = i; ext[-1] = l[i]
        prev = i
    return None


def pivots(h, l, k, nb):
    lo, hi = [], []
    for q in range(k, nb - k):
        w = slice(q - k, q + k + 1)
        if not (np.all(~np.isnan(l[w])) and np.all(~np.isnan(h[w]))):
            continue
        if all(l[q] < l[q - j] for j in range(1, k + 1)) and all(l[q] <= l[q + j] for j in range(1, k + 1)):
            lo.append(q)
        if all(h[q] > h[q - j] for j in range(1, k + 1)) and all(h[q] >= h[q + j] for j in range(1, k + 1)):
            hi.append(q)
    return lo, hi


def find_b(o, h, l, c, v, vw, at, p):
    """First Setup-B signal of the day (either side). Returns (side, i, stop) or None."""
    plo, phi = pivots(h, l, p.piv, p.nb)
    for t in range(p.win_lo, p.win_hi + 1):
        if not (ok(c[t]) and ok(vw[t]) and ok(at[t]) and at[t] > 0 and ok(o[t + 1]) and v[t] > 0):
            continue
        a = at[t]
        for s in (1, -1):
            if s * (vw[t] - c[t]) < p.far * a:          # long needs close >= far*ATR below VWAP; short above
                continue
            piv = [q for q in (plo if s > 0 else phi) if q + p.piv <= t - 1]
            hit = None
            for jj in range(len(piv) - 1, 0, -1):
                p2 = piv[jj]
                for ii in range(jj - 1, -1, -1):
                    p1 = piv[ii]
                    if p2 - p1 < p.spacing:
                        continue
                    if s > 0:
                        if abs(l[p1] - l[p2]) > p.tol * a:
                            continue
                        L = min(l[p1], l[p2])
                        if np.nanmin(l[p1:t]) < L:
                            continue
                        if l[t] < L - p.sweep * a and c[t] > L:
                            hit = l[t] - p.buf * a
                    else:
                        if abs(h[p1] - h[p2]) > p.tol * a:
                            continue
                        Hh = max(h[p1], h[p2])
                        if np.nanmax(h[p1:t]) > Hh:
                            continue
                        if h[t] > Hh + p.sweep * a and c[t] < Hh:
                            hit = h[t] + p.buf * a
                    if hit is not None:
                        break
                if hit is not None:
                    break
            if hit is None:
                continue
            risk = s * (c[t] - hit)
            if p.rmin <= risk / c[t] <= p.rmax and s * (vw[t] - c[t]) >= p.rr * risk:
                return s, t, hit
    return None


def manage(s, e, stop, tgt_fixed, dyn, o, h, l, c, vw, p):
    entry = o[e]; st = stop
    tgt0 = vw[e - 1] if dyn else tgt_fixed
    be_level = entry + 0.5 * (tgt0 - entry)
    for j in range(e, p.exit_idx):
        if not (ok(o[j]) and ok(h[j]) and ok(l[j])):
            continue
        tgt = vw[j - 1] if dyn else tgt_fixed
        if s > 0:
            if o[j] <= st:
                return j, o[j], "stop_gap"
            if l[j] <= st:
                return j, st, "stop"
            if ok(tgt) and h[j] > tgt:
                return j, max(tgt, o[j]), "target"
            if p.be and h[j] >= be_level:
                st = max(st, entry)
        else:
            if o[j] >= st:
                return j, o[j], "stop_gap"
            if h[j] >= st:
                return j, st, "stop"
            if ok(tgt) and l[j] < tgt:
                return j, min(tgt, o[j]), "target"
            if p.be and l[j] <= be_level:
                st = min(st, entry)
    x = p.exit_idx
    if ok(o[x]):
        return x, o[x], "time"
    for j in range(x - 1, e - 1, -1):
        if ok(c[j]):
            return j, c[j], "time"
    return e, entry, "time"


def widen(s, c, stop):
    """Minimum-width stop (0.40%); None if the stop ends up more than 1.50% from the signal close."""
    stop = min(stop, c * (1 - MINW)) if s > 0 else max(stop, c * (1 + MINW))
    return stop if s * (c - stop) / c <= MAXW else None


def rvol(arr, good):
    """Cumulative volume today / mean cumulative volume at the same bar over the previous good sessions (max 10, min 5)."""
    v, c = arr["v"], arr["c"]
    vol = np.nan_to_num(v.copy(), nan=0.0)
    fix = (vol[:, 0] <= 0) & ~np.isnan(c[:, 0])
    vol[fix, 0] = np.nan_to_num(v[fix, 1], nan=0.0)          # same 09:15 fix as the VWAP
    vol = np.where(np.isnan(c), 0.0, vol)
    cum = np.cumsum(vol, 1)
    out = np.full(cum.shape, np.nan); hist = []
    for r in range(cum.shape[0]):
        if not good[r]:
            continue
        if len(hist) >= 5:
            base = cum[hist[-10:]].mean(0)
            with np.errstate(all="ignore"):
                out[r] = np.where(base > 0, cum[r] / base, np.nan)
        hist.append(r)
    return out


def find_u1(o, h, l, c, v, vw, at, rv, br, p):
    """Setup A of SPEC.md + RVOL >= 2 + breadth alignment + minimum-width stop."""
    ws = {1: None, -1: None}; ext = {1: -np.inf, -1: np.inf}; prev = None
    for i in range(p.nb):
        if not (ok(c[i]) and ok(vw[i])):
            continue
        for s in (1, -1):
            if ws[s] is None:
                continue
            if s * (c[i] - vw[i]) < 0 or i - ws[s] > p.watch:
                ws[s] = None; continue
            a = at[i]
            if ok(a) and a > 0 and p.win_lo <= i <= p.win_hi:
                if s > 0:
                    sig = (ext[s] - vw[i] >= p.ext * a) and (l[i] <= vw[i] + p.touch * a) and c[i] > vw[i] and c[i] > o[i]
                    stop = min(l[i], vw[i]) - p.buf * a; mk = ok(br[i]) and br[i] >= 0.55
                else:
                    sig = (vw[i] - ext[s] >= p.ext * a) and (h[i] >= vw[i] - p.touch * a) and c[i] < vw[i] and c[i] < o[i]
                    stop = max(h[i], vw[i]) + p.buf * a; mk = ok(br[i]) and br[i] <= 0.45
                if sig and mk and ok(rv[i]) and rv[i] >= RVOL_MIN and ok(o[i + 1]) and v[i] > 0:
                    st = widen(s, c[i], stop)
                    if st is not None:
                        return s, i, st
            ext[s] = max(ext[s], h[i]) if s > 0 else min(ext[s], l[i])
        if prev is not None:
            if c[i] > vw[i] and c[prev] <= vw[prev]:
                ws[1] = i; ext[1] = h[i]
            if c[i] < vw[i] and c[prev] >= vw[prev]:
                ws[-1] = i; ext[-1] = l[i]
        prev = i
    return None


def find_u3(o, h, l, c, v, vw, at, br, p):
    """Capitulation sweep of a double bottom/top at the day's extreme, then a confirmation bar (the signal)."""
    plo, phi = pivots(h, l, p.piv, p.nb)
    for t in range(p.win_lo - 1, p.win_hi):
        q = t + 1
        if not (ok(c[t]) and ok(c[q]) and ok(vw[q]) and ok(at[t]) and at[t] > 0 and ok(at[q]) and at[q] > 0
                and ok(o[q + 1]) and v[t] > 0 and v[q] > 0):
            continue
        prev12 = v[max(0, t - 12):t]; prev12 = prev12[~np.isnan(prev12)]
        if len(prev12) < 6 or not v[t] >= 2.0 * prev12.mean():
            continue
        a = at[t]
        for s in (1, -1):
            piv = [x for x in (plo if s > 0 else phi) if x + p.piv <= t - 1]
            found = False
            for jj in range(len(piv) - 1, 0, -1):
                p2 = piv[jj]
                for ii in range(jj - 1, -1, -1):
                    p1 = piv[ii]
                    if p2 - p1 < p.spacing:
                        continue
                    if s > 0:
                        if abs(l[p1] - l[p2]) > p.tol * a:
                            continue
                        L = min(l[p1], l[p2])
                        if np.nanmin(l[p1:t]) < L or (p1 > 0 and np.nanmin(l[0:p1]) < L):
                            continue
                        found = l[t] < L - p.sweep * a and c[t] > L
                    else:
                        if abs(h[p1] - h[p2]) > p.tol * a:
                            continue
                        Hh = max(h[p1], h[p2])
                        if np.nanmax(h[p1:t]) > Hh or (p1 > 0 and np.nanmax(h[0:p1]) > Hh):
                            continue
                        found = h[t] > Hh + p.sweep * a and c[t] < Hh
                    if found:
                        break
                if found:
                    break
            if not found:
                continue
            if (s > 0 and not c[q] > h[t]) or (s < 0 and not c[q] < l[t]):
                continue
            if s * (vw[q] - c[q]) < 1.5 * at[q]:
                continue
            st = widen(s, c[q], (l[t] - p.buf * a) if s > 0 else (h[t] + p.buf * a))
            if st is None:
                continue
            if s * (vw[q] - c[q]) < 1.5 * s * (c[q] - st):
                continue
            if not ok(br[q]) or (s > 0 and not br[q] > 0.25) or (s < 0 and not br[q] < 0.75):
                continue
            return s, q, st
    return None


def find_u4(o, h, l, c, v, vw, at, rv, br, p):
    """One decision at the 10:10 bar close: in-play stock trending with VWAP and the market."""
    i = BARS5.index("10:10")
    if not (ok(c[i]) and ok(vw[i]) and ok(vw[i - 6]) and ok(at[i]) and at[i] > 0 and ok(o[i + 1]) and ok(rv[i])
            and rv[i] >= RVOL_MIN and ok(br[i]) and v[i] > 0):
        return None
    vo = [x for x in o[:i + 1] if ok(x)]
    if not vo:
        return None
    o0 = vo[0]
    if c[i] > vw[i] and c[i] > o0 and vw[i] > vw[i - 6] and br[i] >= 0.5:
        s, stop = 1, vw[i] - 0.25 * at[i]
    elif c[i] < vw[i] and c[i] < o0 and vw[i] < vw[i - 6] and br[i] <= 0.5:
        s, stop = -1, vw[i] + 0.25 * at[i]
    else:
        return None
    st = widen(s, c[i], stop)
    return (s, i, st) if st is not None else None


def manage_trail(s, e, stop, o, h, l, c, vw, at, p):
    """Initial stop + VWAP trail (close > 0.25 ATR on the wrong side -> exit next open) + 15:10 exit."""
    st = stop; entry = o[e]
    for j in range(e, p.exit_idx):
        if not (ok(o[j]) and ok(h[j]) and ok(l[j])):
            continue
        if s > 0:
            if o[j] <= st:
                return j, o[j], "stop_gap"
            if l[j] <= st:
                return j, st, "stop"
        else:
            if o[j] >= st:
                return j, o[j], "stop_gap"
            if h[j] >= st:
                return j, st, "stop"
        if ok(c[j]) and ok(vw[j]) and ok(at[j]) and s * (c[j] - vw[j]) < -TRAIL_K * at[j]:
            for k in range(j + 1, p.exit_idx + 1):
                if ok(o[k]):
                    return k, o[k], ("vwap_trail" if k < p.exit_idx else "time")
            return j, c[j], "vwap_trail"
    x = p.exit_idx
    if ok(o[x]):
        return x, o[x], "time"
    for j in range(x - 1, e - 1, -1):
        if ok(c[j]):
            return j, c[j], "time"
    return e, entry, "time"
